type Authenticator interface {
    Authenticate(ctx context.Context, creds Credentials) (Principal, error)
}

var registry = map[string]Authenticator{
    "password": PasswordVerifier{Users: users},
    "bearer":   JWTVerifier{Keys: jwks, Issuer: issuer},
}

func login(w http.ResponseWriter, r *http.Request, scheme string) {
    authenticator, ok := registry[scheme]
    if !ok {
        http.Error(w, "unknown authentication scheme", http.StatusBadRequest)
        return
    }
    principal, err := authenticator.Authenticate(r.Context(), parse(r))
    if err != nil {
        http.Error(w, "authentication failed", http.StatusUnauthorized)
        return
    }
    _ = principal // attach only the verified principal to request context
}
